    13		private async getDB(): Promise<IDBDatabase> {
    14			if (!this.dbPromise) {
    15				this.dbPromise = new Promise((resolve, reject) => {
    16					const request = indexedDB.open(this.config.dbName, this.config.version);
    17	
    18					request.onerror = () => {
    19						this.dbPromise = null;
    20						reject(request.error);
    21					};
    22					request.onblocked = () => {
    23						console.warn(`${this.config.dbName} storage upgrade is blocked by an older open tab.`);
    24					};
    25					request.onsuccess = () => {
    26						const db = request.result;
    27						db.onversionchange = () => {
    28							db.close();
    29							this.dbPromise = null;
    30						};
    31						resolve(db);
    32					};
    33	
    34					request.onupgradeneeded = (_event) => {
    35						const db = request.result;
    36	
    37						// Declaratively reconcile stores and indices on every version bump.
    38						// Earlier versions only configured indices when creating a store,
    39						// which made later schema versions unable to add an index safely.
    40						for (const storeConfig of this.config.stores) {
    41							const store = db.objectStoreNames.contains(storeConfig.name)
    42								? request.transaction!.objectStore(storeConfig.name)
    43								: db.createObjectStore(storeConfig.name, {
    44									keyPath: storeConfig.keyPath,
    45									autoIncrement: storeConfig.autoIncrement,
    46								});
    47	
    48							if (storeConfig.indices) {
    49								for (const indexConfig of storeConfig.indices) {
    50									if (!store.indexNames.contains(indexConfig.name)) {
    51										store.createIndex(indexConfig.name, indexConfig.keyPath, {
    52											unique: indexConfig.unique,
    53										});
    54									}
    55							}
    56						}
    57					};
    58				});
    59			}
    60	
    61			return this.dbPromise;
    62		}
    63	
    64		private promisifyRequest<T>(request: IDBRequest<T>): Promise<T> {
    65			return new Promise((resolve, reject) => {
    66				request.onsuccess = () => resolve(request.result);
    67				request.onerror = () => reject(request.error);
    68			});
    69		}
