    71		async get<T = unknown>(storeName: string, key: string): Promise<T | null> {
    72			const db = await this.getDB();
    73			const tx = db.transaction(storeName, "readonly");
    74			const store = tx.objectStore(storeName);
    75			const result = await this.promisifyRequest(store.get(key));
    76			return result ?? null;
    77		}
    78	
    79		async set<T = unknown>(storeName: string, key: string, value: T): Promise<void> {
    80			const db = await this.getDB();
    81			const tx = db.transaction(storeName, "readwrite");
    82			const store = tx.objectStore(storeName);
    83			// If store has keyPath, only pass value (in-line key)
    84			// Otherwise pass both value and key (out-of-line key)
    85			if (store.keyPath) {
    86				await this.promisifyRequest(store.put(value));
    87			} else {
    88				await this.promisifyRequest(store.put(value, key));
    89			}
    90		}
    91	
    92		async delete(storeName: string, key: string): Promise<void> {
    93			const db = await this.getDB();
    94			const tx = db.transaction(storeName, "readwrite");
    95			const store = tx.objectStore(storeName);
    96			await this.promisifyRequest(store.delete(key));
    97		}
